/** Serialize one collection of groups, applying ?filter to its members. */
export function serializeGroupCollection(
  groups: Map<string, GroupEntity>,
  opts: SerializeOptions,
  path: string[],
): Json {
  const out: Json = {};
  for (const [gid, group] of groups) {
    const serialized = serializeGroup(group, opts, path);
    if (!matchesFilter(serialized, opts.filter)) continue;
    out[gid] = serialized;
  }
  return out;
}

export function serializeRegistry(tree: RegistryTree, opts: SerializeOptions): Json {
  const out: Json = {
    specversion: SPEC_VERSION,
    registryid: tree.registryid,
    self: ref(opts, '/'),
    xid: '/',
    epoch: tree.epoch,
    createdat: tree.createdat,
    modifiedat: tree.modifiedat,
  };
  if (tree.name !== undefined) out['name'] = tree.name;
  if (tree.description !== undefined) out['description'] = tree.description;

  if (opts.capabilities && shouldInline(opts.inline, ['capabilities'])) {
    out['capabilities'] = opts.capabilities;
  }
  if (opts.model && shouldInline(opts.inline, ['model'])) {
    out['model'] = opts.model;
  }
  if (opts.model && shouldInline(opts.inline, ['modelsource'])) {
    out['modelsource'] = opts.model;
  }

  for (const [plural, groups] of tree.groups) {
    const path = [plural];
    collection(out, plural, opts, '/', path, serializeGroupCollection(groups, opts, path), groups.size);
  }
  return out;
}

