// Package xregistry is a read-only client for the Intropy message
// registry, an xRegistry-compliant server of CloudEvents message
// definitions, payload schemas, and the endpoints that produce and consume
// them. The registry is git-authored and serves a conformant read-only
// API; this package fetches its /export document and resolves the joins
// (message → producing endpoint → channel) that subscribers care about.
//
// It is unrelated to internal/registry, the OCI client for releases and
// templates — the two registries share a name and nothing else.
package xregistry

import "encoding/json"

// Export is the registry's /export document: the whole registry in one
// document view, with all collections inlined. The server guarantees it is
// byte-identical to GET /?doc&inline=*,capabilities,modelsource, so models
// built from it cannot drift from what the individual entity paths serve.
type Export struct {
	RegistryID  string `json:"registryid"`
	Name        string `json:"name"`
	Description string `json:"description"`

	MessageGroups map[string]*MessageGroup `json:"messagegroups"`
	SchemaGroups  map[string]*SchemaGroup  `json:"schemagroups"`
	Endpoints     map[string]*Endpoint     `json:"endpoints"`
}

// MessageGroup is a group of related messages. In the export's document
// view a resource carries only its own attributes — the message attributes
// a subscriber needs (envelope metadata, dataschema reference) live on the
// default version under Versions, not on the Message itself.
type MessageGroup struct {
	MessageGroupID string `json:"messagegroupid"`
	Xid            string `json:"xid"`
	Name           string `json:"name"`
	Description    string `json:"description"`
	Envelope       string `json:"envelope"`
	Protocol       string `json:"protocol"`

	Messages map[string]*Message `json:"messages"`
}

// Message is one CloudEvents definition.
type Message struct {
	MessageID   string `json:"messageid"`
	Xid         string `json:"xid"`
	Name        string `json:"name"`
	Description string `json:"description"`

	Versions map[string]*MessageVersion `json:"versions"`
}

// MessageVersion is one version of a message. Message attributes are read
// from the default version — see MessageGroup.
type MessageVersion struct {
	VersionID string `json:"versionid"`
	IsDefault bool   `json:"isdefault"`

	Envelope         string                    `json:"envelope"`
	EnvelopeMetadata map[string]EnvelopeAttr   `json:"envelopemetadata"`
	Protocol         string                    `json:"protocol"`
	DataschemaFormat string                    `json:"dataschemaformat"`
	DataschemaXid    string                    `json:"dataschemaxid"`
	Datacontenttype  string                    `json:"datacontenttype"`
}

// EnvelopeAttr is one CloudEvents attribute constraint from envelopemetadata.
// Value is absent for attributes the producer fills per event (subject, id,
// time); when present it is a fixed value such as the CloudEvents type.
type EnvelopeAttr struct {
	Value       json.RawMessage `json:"value"`
	Type        string          `json:"type"`
	Required    bool            `json:"required"`
	Description string          `json:"description"`
}

// StringValue returns the attribute's fixed value as a string, reporting
// false when the attribute has no value or it is not a JSON string.
func (a EnvelopeAttr) StringValue() (string, bool) {
	if len(a.Value) == 0 {
		return "", false
	}
	var s string
	if err := json.Unmarshal(a.Value, &s); err != nil {
		return "", false
	}
	return s, true
}

// SchemaGroup is a group of payload schemas, mirroring a message group.
type SchemaGroup struct {
	SchemaGroupID string `json:"schemagroupid"`
	Xid           string `json:"xid"`

	Schemas map[string]*Schema `json:"schemas"`
}

// Schema is one payload schema. As with messages, format attributes live on
// the default version in the export's document view.
type Schema struct {
	SchemaID string `json:"schemaid"`
	Xid      string `json:"xid"`

	Versions map[string]*SchemaVersion `json:"versions"`
}

// SchemaVersion is one version of a schema. Document holds the inlined
// schema document (JSON Schema), present because /export inlines everything.
type SchemaVersion struct {
	VersionID       string `json:"versionid"`
	IsDefault       bool   `json:"isdefault"`
	Format          string `json:"format"`
	FormatValidated bool   `json:"formatvalidated"`

	Document json.RawMessage `json:"schema"`
}

// Endpoint is a producer or consumer of a message group. Unlike messages
// and schemas it has no versions — its attributes sit on the entity
// itself. Channel names where the endpoint's messages flow, by convention
// "<pubsub>/<topic>"; see SplitChannel.
type Endpoint struct {
	EndpointID    string   `json:"endpointid"`
	Xid           string   `json:"xid"`
	Name          string   `json:"name"`
	Description   string   `json:"description"`
	Usage         []string `json:"usage"`
	Channel       string   `json:"channel"`
	Envelope      string   `json:"envelope"`
	Protocol      string   `json:"protocol"`
	MessageGroups []string `json:"messagegroups"`
}

// DefaultVersion returns the message's default version. A version flagged
// isdefault wins; a message with exactly one version falls back to it,
// because a registry mid-edit is still worth serving — the same leniency
// the server applies to unresolved references.
func (m *Message) DefaultVersion() *MessageVersion {
	return defaultVersion(m.Versions)
}

// DefaultVersion returns the schema's default version, with the same
// single-version fallback as Message.DefaultVersion.
func (s *Schema) DefaultVersion() *SchemaVersion {
	return defaultVersion(s.Versions)
}

func defaultVersion[V interface{ GetIsDefault() bool }](versions map[string]V) V {
	var only V
	var zero V
	count := 0
	for _, v := range versions {
		if v.GetIsDefault() {
			return v
		}
		only = v
		count++
	}
	if count == 1 {
		return only
	}
	return zero
}

// GetIsDefault implements the version constraint for MessageVersion.
func (v *MessageVersion) GetIsDefault() bool { return v.IsDefault }

// GetIsDefault implements the version constraint for SchemaVersion.
func (v *SchemaVersion) GetIsDefault() bool { return v.IsDefault }

