package xregistry

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"
)

// Client fetches the registry's export document over HTTP. It is read-only
// because the registry is: every write verb there answers 405.
type Client struct {
	baseURL   string
	http      *http.Client
	userAgent string
}

type options struct {
	httpClient *http.Client
	userAgent  string
}

// Option customises NewClient.
type Option func(*options)

// WithHTTPClient replaces the default HTTP client.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) { o.httpClient = c }
}

// WithUserAgent sets the User-Agent header on registry requests.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}

// NewClient builds a Client for the registry at baseURL. The URL must be
// absolute; a trailing slash is stripped so path joining is unambiguous.
func NewClient(baseURL string, opts ...Option) (*Client, error) {
	u, err := url.Parse(baseURL)
	if err != nil || !u.IsAbs() {
		return nil, fmt.Errorf("registry URL %q is not an absolute URL (e.g. https://registry.example.com)", baseURL)
	}
	o := options{httpClient: http.DefaultClient}
	for _, opt := range opts {
		opt(&o)
	}
	return &Client{
		baseURL:   strings.TrimSuffix(baseURL, "/"),
		http:      o.httpClient,
		userAgent: o.userAgent,
	}, nil
}

// Export fetches GET /export: the whole registry in one document, so a
// command or a create run resolves every join from a single fetch and can
// never observe two collections at different points in time.
func (c *Client) Export(ctx context.Context) (*Export, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+"/export", nil)
	if err != nil {
		return nil, fmt.Errorf("get export: %w", err)
	}
	// Explicit rather than inherited: the registry negotiates HTML vs JSON on
	// Accept, and only a client that asks for JSON specifically is immune to
	// future portal routes.
	req.Header.Set("Accept", "application/json")
	if c.userAgent != "" {
		req.Header.Set("User-Agent", c.userAgent)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return nil, fmt.Errorf("get export from %s: %w", c.baseURL, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("get export from %s: registry returned %s", c.baseURL, resp.Status)
	}
	var doc Export
	if err := json.NewDecoder(resp.Body).Decode(&doc); err != nil {
		return nil, fmt.Errorf("get export from %s: parse /export: %w", c.baseURL, err)
	}
	return &doc, nil
}

// ResolvedMessage is a message joined with its group and default version —
// the unit every consumer actually works with, since message attributes
// live on the version in the export document.
type ResolvedMessage struct {
	Group   *MessageGroup
	Message *Message
	Version *MessageVersion
}

// CloudEventsType returns the fixed value of the CloudEvents "type"
// attribute, which by registry convention equals the message id.
func (r *ResolvedMessage) CloudEventsType() string {
	attr, ok := r.Version.EnvelopeMetadata["type"]
	if !ok {
		return ""
	}
	s, _ := attr.StringValue()
	return s
}

// MessageNotFoundError reports a reference no message in the registry
// matches.
type MessageNotFoundError struct {
	Ref string
}

func (e *MessageNotFoundError) Error() string {
	return fmt.Sprintf("message %q not found in registry", e.Ref)
}

// AmbiguousMessageError reports a bare message id that names a message in
// more than one group — the registry cannot prevent two groups declaring
// the same CloudEvents type, so the caller must disambiguate with a full
// xid.
type AmbiguousMessageError struct {
	Ref  string
	Xids []string
}

func (e *AmbiguousMessageError) Error() string {
	return fmt.Sprintf("message %q matches multiple messages\nuse a full xid: %s", e.Ref, strings.Join(e.Xids, ", "))
}

// ResolveMessage finds one message by bare message id
// ("io.intropy.maxbo.product.export") or full xid
// ("/messagegroups/<gid>/messages/<mid>"). A bare id must match exactly one
// message; zero matches is a MessageNotFoundError, more than one an
// AmbiguousMessageError listing the xids.
func (e *Export) ResolveMessage(ref string) (*ResolvedMessage, error) {
	if strings.HasPrefix(ref, "/") {
		return e.resolveXid(ref)
	}
	var matches []*ResolvedMessage
	for _, g := range e.MessageGroups {
		for id, m := range g.Messages {
			if id == ref {
				matches = append(matches, &ResolvedMessage{Group: g, Message: m, Version: m.DefaultVersion()})
			}
		}
	}
	switch len(matches) {
	case 0:
		return nil, &MessageNotFoundError{Ref: ref}
	case 1:
		return matches[0], nil
	}
	xids := make([]string, 0, len(matches))
	for _, m := range matches {
		xids = append(xids, m.Message.Xid)
	}
	sort.Strings(xids)
	return nil, &AmbiguousMessageError{Ref: ref, Xids: xids}
}

// resolveXid resolves a full message xid of the form
// /messagegroups/<gid>/messages/<mid>. Anything else is a not-found: the
// registry has other hierarchies (schemagroups), and a schema xid pasted
// where a message belongs should read as "no such message", not as a
// confusing nil deeper in.
func (e *Export) resolveXid(xid string) (*ResolvedMessage, error) {
	parts := strings.Split(strings.TrimPrefix(xid, "/"), "/")
	if len(parts) != 4 || parts[0] != "messagegroups" || parts[2] != "messages" {
		return nil, &MessageNotFoundError{Ref: xid}
	}
	g, ok := e.MessageGroups[parts[1]]
	if !ok {
		return nil, &MessageNotFoundError{Ref: xid}
	}
	m, ok := g.Messages[parts[3]]
	if !ok {
		return nil, &MessageNotFoundError{Ref: xid}
	}
	return &ResolvedMessage{Group: g, Message: m, Version: m.DefaultVersion()}, nil
}

// ProducerEndpointsFor returns the endpoints that produce a message group,
// sorted by endpoint id for deterministic output. An empty result is not an
// error: it means the registry has not declared who publishes the group,
// which callers surface as an authoring gap with its own message.
func (e *Export) ProducerEndpointsFor(groupID string) []*Endpoint {
	xid := "/messagegroups/" + groupID
	var out []*Endpoint
	for _, ep := range e.Endpoints {
		if !hasUsage(ep, "producer") {
			continue
		}
		for _, g := range ep.MessageGroups {
			if g == xid {
				out = append(out, ep)
				break
			}
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].EndpointID < out[j].EndpointID })
	return out
}

func hasUsage(ep *Endpoint, want string) bool {
	for _, u := range ep.Usage {
		if u == want {
			return true
		}
	}
	return false
}

// SplitChannel splits an endpoint channel into its pubsub component and
// topic. The registry's naming convention is "<pubsub>/<topic>" — the same
// two values the CLI's wiring vocabulary records separately.
func SplitChannel(channel string) (pubsub, topic string, err error) {
	pubsub, topic, ok := strings.Cut(channel, "/")
	if !ok || pubsub == "" || topic == "" {
		return "", "", fmt.Errorf("channel %q is not <pubsub>/<topic>", channel)
	}
	return pubsub, topic, nil
}

