func TestResolveRegistryURLPrecedence(t *testing.T) {
	t.Setenv(EnvRegistryURL, "")
	file := Config{
		RegistryURL: "https://file.example.com",
		Contexts:    map[string]Context{"c": {RegistryURL: "https://ctx.example.com"}},
	}

	// Top-level file value applies with no context selected.
	if got := file.Resolve(Flags{}).RegistryURL; got != "https://file.example.com" {
		t.Errorf("RegistryURL = %q", got)
	}

	// The context rung overrides the top-level default.
	file.CurrentContext = "c"
	if got := file.Resolve(Flags{}).RegistryURL; got != "https://ctx.example.com" {
		t.Errorf("RegistryURL = %q", got)
	}

	// Environment beats context, flag beats environment.
	t.Setenv(EnvRegistryURL, "https://env.example.com")
	if got := file.Resolve(Flags{}).RegistryURL; got != "https://env.example.com" {
		t.Errorf("RegistryURL = %q", got)
	}
	if got := file.Resolve(Flags{RegistryURL: "https://flag.example.com"}).RegistryURL; got != "https://flag.example.com" {
		t.Errorf("RegistryURL = %q", got)
	}
}

