	Message     string             `json:"message"`
	Xid         string             `json:"xid"`
	Name        string             `json:"name,omitempty"`
	Description string             `json:"description,omitempty"`
	Group       string             `json:"group"`
	Type        string             `json:"type,omitempty"`
	Source      string             `json:"source,omitempty"`
	Envelope    string             `json:"envelope,omitempty"`
	Protocol    string             `json:"protocol,omitempty"`
	Dataschema  string             `json:"dataschema,omitempty"`
	Schema      *schemaReference   `json:"schema,omitempty"`
	Producers   []producerChannel  `json:"producers"`
}

type schemaReference struct {
	ID      string `json:"id"`
	Version string `json:"version,omitempty"`
	Format  string `json:"format,omitempty"`
}

type producerChannel struct {
	Endpoint string `json:"endpoint"`
	Pubsub   string `json:"pubsub"`
	Topic    string `json:"topic"`
}

var messageShowCmd = &cobra.Command{
	Use:   "show <message>",
	Short: "Show one message and how to subscribe to it",
	Long: "Show one message from the registry: its description, CloudEvents type and source, the payload " +
		"schema reference, and the subscription recipe — the pubsub component and topic a subscriber binds " +
		"to, derived from the channel of the endpoint that produces it. The argument is the message id (the " +
		"CloudEvents type) or a full xid (/messagegroups/<group>/messages/<id>); a bare id that names a " +
		"message in more than one group is refused with the matching xids. Use --output json for a " +
		"machine-readable document.",
	Args: usageArgs(cobra.ExactArgs(1)),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(messageShowOpts.output, "plain", "json"); err != nil {
			return err
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		doc, err := fetchExport(ctx, messageShowOpts.registryURL)
		if err != nil {
			return err
		}
		resolved, err := resolveMessage(doc, args[0])
		if err != nil {
			return err
		}
		d := showDocument(doc, resolved)

		if messageShowOpts.output == "json" {
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(d)
		}

		out := cmd.OutOrStdout()
		fmt.Fprintln(out, d.Message)
		if d.Name != "" {
			fmt.Fprintf(out, "  %s\n", d.Name)
		}
		if d.Description != "" {
			fmt.Fprintf(out, "  %s\n", d.Description)
		}
		fmt.Fprintln(out)
		printField(out, "group", d.Group)
		printField(out, "type", d.Type)
		printField(out, "source", d.Source)
		printField(out, "envelope", d.Envelope)
		printField(out, "protocol", d.Protocol)
		printField(out, "dataschema", d.Dataschema)
		if d.Schema != nil {
			printField(out, "schema version", d.Schema.Version)
		}
		fmt.Fprintln(out)
		if len(d.Producers) == 0 {
			fmt.Fprintf(out, "no producer endpoint declared for %s\n", d.Group)
			return nil
		}
		fmt.Fprintln(out, "subscribe:")
		for _, p := range d.Producers {
			fmt.Fprintf(out, "  pubsub:   %s\n", p.Pubsub)
			fmt.Fprintf(out, "  topic:    %s\n", p.Topic)
			fmt.Fprintf(out, "  producer: %s\n", p.Endpoint)
		}
		return nil
	},
}

// showDocument joins a resolved message with its schema and producer
// channels. A dangling dataschemaxid is shown as-is with no resolved
// schema — the registry keeps unresolved references with a warning, and
// hiding them here would make that warning invisible to the reader.
func showDocument(doc *xregistry.Export, r *xregistry.ResolvedMessage) messageShowDocument {
	d := messageShowDocument{
		Message: r.Message.MessageID,
		Xid:     r.Message.Xid,
		Name:    r.Message.Name,
		Group:   r.Group.MessageGroupID,
	}
	if v := r.Version; v != nil {
		d.Type = r.CloudEventsType()
		d.Envelope = v.Envelope
		d.Protocol = v.Protocol
		d.Dataschema = v.DataschemaXid
		if attr, ok := v.EnvelopeMetadata["source"]; ok {
			d.Source, _ = attr.StringValue()
		}
	}
	if d.Dataschema != "" {
		if s, err := doc.ResolveSchema(d.Dataschema); err == nil {
			d.Schema = &schemaReference{ID: s.Schema.SchemaID}
			if s.Version != nil {
				d.Schema.Version = s.Version.VersionID
				d.Schema.Format = s.Version.Format
			}
		}
	}
	for _, ep := range doc.ProducerEndpointsFor(r.Group.MessageGroupID) {
		pubsub, topic, err := xregistry.SplitChannel(ep.Channel)
		if err != nil {
			continue
		}
		d.Producers = append(d.Producers, producerChannel{Endpoint: ep.EndpointID, Pubsub: pubsub, Topic: topic})
	}
	return d
}

// printField prints one aligned key-value line, skipping empty values so
// the detail view never shows a label with nothing after it.
func printField(out *os.File, key, value string) {
	if value == "" {
		return
	}
	fmt.Fprintf(out, "%-14s%s\n", key+":", value)
}

func init() {
	f := messageShowCmd.Flags()
	f.StringVar(&messageShowOpts.registryURL, "registry-url", "", flagUsageRegistryURL)
	f.StringVarP(&messageShowOpts.output, "output", "o", "plain", flagUsageOutput)
	messageCmd.AddCommand(messageShowCmd)
}

